/**
 * Match a URL path against a slot path pattern.
 * `*` matches a single path segment. No `**` in v1.
 */
export declare function matchPathPattern(pathname: string, pathPattern: string): boolean;
/**
 * Extract pathname from a full URL or path-only string.
 */
export declare function pathnameFromUrl(url: string): string;
/**
 * Extract hostname from a full URL, or undefined for path-only.
 */
export declare function hostFromUrl(url: string): string | undefined;
